import{_ as i,o as t,c as a,ak as o}from"./chunks/framework.CMoRfRvB.js";const u=JSON.parse('{"title":"What is dice notation?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notation/index.md","filePath":"guide/notation/index.md","lastUpdated":1794064379000}'),n={name:"guide/notation/index.md"};function s(l,e,d,r,h,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-dice-notation" tabindex="-1">What is dice notation? <a class="header-anchor" href="#what-is-dice-notation" aria-label="Permalink to &quot;What is dice notation?&quot;">​</a></h1><p>Dice notation is a compact way to describe a dice roll. It tells the library which dice to roll, how to modify their results, and how to calculate the total.</p><p>For example, <code>2d6+3</code> means “roll two six-sided dice, add their results together, then add 3”.</p><p>RPG Dice Roller uses familiar <a href="https://en.wikipedia.org/wiki/Dice_notation" target="_blank" rel="noreferrer">dice notation</a>, extended with modifiers, roll groups and mathematical expressions to support more complex game mechanics.</p><h2 id="reading-a-notation" tabindex="-1">Reading a notation <a class="header-anchor" href="#reading-a-notation" aria-label="Permalink to &quot;Reading a notation&quot;">​</a></h2><p>A basic dice notation consists of a quantity, the letter <code>d</code>, and the number of sides:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2d6</span></span></code></pre></div><p>Here, <code>2</code> is the number of dice to roll and <code>6</code> is the number of sides on each die. If you leave out the quantity, it defaults to one: <code>d6</code> is equivalent to <code>1d6</code>.</p><p>You can build on this by adding modifiers and maths. For example:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4d6d1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>This tells the library to:</p><ol><li>Roll four six-sided dice.</li><li>Drop the lowest result.</li><li>Add the remaining results together, then add 5.</li></ol><p>Try rolling it below. You can also edit the notation to experiment with different dice and values.</p><p>::: roller 4d6d1 + 5 :::</p><h2 id="notation-reference" tabindex="-1">Notation reference <a class="header-anchor" href="#notation-reference" aria-label="Permalink to &quot;Notation reference&quot;">​</a></h2><p>The following pages explain the different parts of the notation and how to combine them:</p><ul><li><a href="./dice.html">Dice</a> — Choose which dice to roll, such as standard, percentile or Fudge dice.</li><li><a href="./modifiers.html">Modifiers</a> — Change how rolls behave, with rules such as exploding, re-rolling, and keeping or dropping results.</li><li><a href="./roll-groups.html">Roll groups</a> — Combine roll expressions into a group and apply modifiers to the group.</li><li><a href="./roll-descriptions.html">Roll descriptions</a> — Add labels or descriptions to identify your rolls.</li><li><a href="./maths.html">Maths</a> — Combine dice rolls with arithmetic, parentheses and mathematical functions.</li></ul>',17)])])}const m=i(n,[["render",s]]);export{u as __pageData,m as default};
